(function(){const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const url=s=>/^(https?:\/\/|assets\/)/.test(s||'')?s:'';window.renderProperty=function(p,opts={}){const prefix=opts.prefix||'';const src=s=>s.startsWith('assets/')?prefix+s:s;const photo=(s,alt,cls='')=>`<figure class="property-figure ${cls}"><img src="${E(src(url(s)))}" alt="${E(alt)}" loading="lazy"><figcaption>현장 안내자료 · CG와 실제는 차이가 있을 수 있습니다.</figcaption></figure>`;const outlink=(l)=>`<a href="${E(l[1])}" target="_blank" rel="noopener">${E(l[0])}<span aria-hidden="true"> ↗</span></a>`;return `<article class="property-detail"><div class="detail-heading"><span class="detail-kicker">${E(p.region)} · ${E(p.type)}</span><h1>${E(p.name)}</h1>${p.buildingName?`<p class="building-name">건물명 ${E(p.buildingName)}</p>`:''}<p class="detail-tagline">${E(p.tag)}</p><div class="detail-actions"><button data-register="${p.id}">관심고객등록</button><a href="tel:16885650">상담 1688-5650</a></div></div>${p.img?photo(p.img,p.name+' 현장 안내 이미지','property-hero-photo'):`<div class="property-visual-pending"><span>⌂</span><b>${E(p.name)}</b><p>현장 사진은 확인된 자료로 추가합니다.</p></div>`}<nav class="detail-tabs" aria-label="현장 상세 메뉴"><button data-detail-section="overview-${p.id}">사업개요</button><button data-detail-section="premium-${p.id}">주요 특징</button><button data-detail-section="location-${p.id}">입지환경</button><button data-detail-section="types-${p.id}">타입안내</button><button data-detail-section="sources-${p.id}">안내자료</button></nav><section class="property-section" id="overview-${p.id}"><p class="eyebrow">PROJECT OVERVIEW</p><h2>사업개요</h2><p class="detail-intro">${E(p.intro)}</p><dl class="detail-overview">${[['현장명',p.name],...(p.buildingName?[['건물명',p.buildingName]]:[]),['위치',p.address],['용도',p.type],['건축규모',p.scale],['공급규모',p.count],['시공',p.builder],['분양가',p.price],['계약·입주 안내','현재 잔여 호실과 조건은 상담 시 확인']].map(([k,v])=>`<div><dt>${E(k)}</dt><dd>${E(v)}</dd></div>`).join('')}</dl></section><section class="property-section detail-premium" id="premium-${p.id}"><p class="eyebrow">LIFE & VALUE</p><h2>현장을 살펴보는 세 가지 기준</h2><div class="detail-highlights">${p.highlights.map((h,i)=>`<div><span>0${i+1}</span><h3>${E(h[0])}</h3><p>${E(h[1])}</p></div>`).join('')}</div></section><section class="property-section" id="location-${p.id}"><p class="eyebrow">LOCATION</p><h2>입지환경</h2><p class="detail-intro">${E(p.location)}</p><div class="property-address"><span>현장 주소</span><b>${E(p.address)}</b><a href="https://map.naver.com/p/search/${encodeURIComponent(p.address)}" target="_blank" rel="noopener">네이버 지도에서 확인</a></div></section><section class="property-section detail-types" id="types-${p.id}"><p class="eyebrow">UNIT PLAN</p><h2>타입안내</h2><div class="type-chips">${p.sizes.map(s=>`<span>${E(s)}</span>`).join('')}</div><p class="detail-intro">${E(p.typesNote||'타입별 구조와 옵션은 공급 안내자료를 기준으로 확인해 주세요. 현재 계약 가능한 호실과 안내된 전체 공급형은 다를 수 있습니다.')}</p>${p.planImg?photo(p.planImg,p.name+' 평면 안내자료','property-plan'):''}${p.gallery?.length?`<div class="detail-gallery">${p.gallery.map((s,i)=>photo(s,p.name+' 공간 안내 '+(i+1))).join('')}</div>`:''}</section><section class="property-section detail-sources" id="sources-${p.id}"><p class="eyebrow">REFERENCE & DOCUMENTS</p><h2>현장 안내자료</h2><div class="official-links">${p.links.map(outlink).join('')}${p.sources.map(outlink).join('')}</div><p class="source-note">확인일 ${E(p.checked)} · 위 링크에서 원본 안내를 확인할 수 있습니다. 최초 공급자료와 현재 판매조건은 구분해 확인해 주세요. 가격·혜택·입주 가능 여부는 담당 상담으로 확인해 주세요.</p></section><section class="property-detail-contact"><div><span>INTEREST REGISTRATION</span><h2>${E(p.name)}</h2><p>원하시는 타입과 궁금한 내용을 남겨주세요.</p></div><button data-register="${p.id}">관심고객등록</button></section></article>`};document.addEventListener('error',e=>{if(e.target?.tagName==='IMG'&&e.target.closest('.property-detail,.property-thumb')){const box=e.target.parentElement;e.target.hidden=true;box.classList.add('image-unavailable');if(!box.querySelector('.unavailable-message')){const text=document.createElement('span');text.className='unavailable-message';text.textContent='이미지는 원본 안내자료에서 확인해 주세요.';box.append(text)}}},true);document.addEventListener('click',e=>{const b=e.target.closest('[data-detail-section]');if(b){const target=document.getElementById(b.dataset.detailSection);target?.scrollIntoView({behavior:'smooth',block:'start'})}})})();
(function(){const original=window.renderProperty;const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));window.renderProperty=function(p,opts={}){if(p.id!=='gdmetro')return original(p,opts);const prefix=opts.prefix||'';const nav=[['overview','사업안내'],['premium','프리미엄'],['location','입지환경'],['types','평면안내'],['interest','관심고객']];let body=original(p,opts);body=body.slice(body.indexOf('<section class="property-section"'));body=body.replace('<h2>사업개요</h2>','<h2>도시의 중심에서 시작하는 일상</h2>');body=body.replace('<section class="property-section detail-premium"','<section class="property-section detail-premium"');body=body.replace('현장을 살펴보는 세 가지 기준','연결되는 교통, 완성되는 생활');const start=body.indexOf('<section class="property-section detail-types"');const end=body.indexOf('<section class="property-section detail-sources"');const plans=`<section class="property-section gd-plans" id="types-gdmetro"><p class="eyebrow">UNIT PLAN</p><h2>평면안내</h2><p class="detail-intro">나에게 맞는 공간을 비교해 보세요. 타입을 선택하면 공식 평면도를 확인할 수 있습니다.</p><div class="gd-plan-tabs" role="group" aria-label="평면 타입 선택">${p.plans.map((t,i)=>`<button type="button" data-gd-plan="${t.id}" aria-pressed="${i===0}">${t.label}</button>`).join('')}</div><div class="gd-plan-display">${p.plans.map((t,i)=>`<figure data-gd-panel="${t.id}" ${i?'hidden':''}><h3>${t.label} TYPE</h3><a href="${E(t.src)}" target="_blank" rel="noopener" aria-label="${t.label} 평면도 원본 크게 보기"><img src="${E(t.src)}" alt="GD메트로타워 ${t.label} 공식 평면도" loading="lazy"></a><figcaption>이미지를 누르면 원본으로 크게 볼 수 있습니다.</figcaption></figure>`).join('')}</div><p class="source-note">공식 평면 안내자료 기준. 가구·마감·면적 및 평면 반전 여부는 실제 공급자료와 견본주택에서 확인해 주세요.</p></section>`;body=body.slice(0,start)+plans+'<div class="gd-plan-registration"><button type="button" data-detail-section="interest-gdmetro">관심고객등록</button></div>'+body.slice(end);body=body.replace('<div class="official-links">',`<div class="gd-price-document"><h3>분양가: 32,475만원대~ <small>(부가세 별도)</small></h3><p>${E(p.priceNote)}</p><details><summary>공식 공급가격표 보기</summary><a href="${prefix+p.supplyImage}" target="_blank" rel="noopener"><img src="${prefix+p.supplyImage}" alt="GD메트로타워 공식 공급금액 및 납부일정표" loading="lazy"></a></details></div><div class="official-links">`);body=body.replace(/<div class="official-links">[\s\S]*?<\/div><p class="source-note">[\s\S]*?<\/p>/,'');body=body.slice(0,body.indexOf('<section class="property-detail-contact">'));
const interest=`<section class="property-section gd-interest" id="interest-gdmetro"><p class="eyebrow">INTEREST REGISTRATION</p><h2>관심고객등록</h2><p class="detail-intro">GD메트로타워에 대해 궁금한 내용을 남겨주세요.</p><form class="gd-interest-form"><div class="gd-fields"><label>이름 <span>*</span><input name="name" autocomplete="name" placeholder="성함을 입력해 주세요" required></label><label>연락처 <span>*</span><input name="phone" type="tel" autocomplete="tel" placeholder="010-0000-0000" required></label></div><label>관심 타입<select name="unit"><option value="">타입을 선택해 주세요</option>${p.plans.map(t=>`<option>${t.label}</option>`).join('')}</select></label><label>문의사항<textarea name="message" rows="4" placeholder="궁금한 내용을 남겨주세요"></textarea></label><details><summary>개인정보 수집·이용 안내</summary><p>현재 온라인 접수 연결 준비 중으로 입력 내용은 전송하거나 저장하지 않습니다. 상담은 대표번호로 문의해 주세요.</p></details><button type="submit">관심고객등록</button><p role="status" class="gd-form-status">온라인 접수 연결 준비 중 · 전화 상담 1688-5650</p></form></section>`;
return `<article class="property-detail gd-detail"><header class="gd-header"><a href="#overview-gdmetro" data-detail-section="overview-gdmetro" class="gd-wordmark">GD메트로타워</a><nav aria-label="GD메트로타워 메뉴">${nav.map(([id,n])=>`<button type="button" data-detail-section="${id}-gdmetro">${n}</button>`).join('')}</nav><a class="gd-phone" href="tel:16885650"><small>대표번호</small>1688-5650</a></header><section class="gd-hero"><img src="${E(p.img)}" alt="GD메트로타워 1920픽셀 원본 조감도" fetchpriority="high"><div class="gd-hero-copy"><p>GD METRO TOWER</p><h1>도시와 일상이<br>가깝게 이어지다.</h1><span>구로디지털단지역 생활권 · 40층 트윈타워</span><b>${E(p.price)} <small>(부가세 별도)</small></b><button type="button" data-detail-section="interest-gdmetro">관심고객 등록</button></div><span class="gd-cg">사업주체 공식 조감도 · 실제와 차이가 있을 수 있습니다.</span></section><div class="gd-stats"><div><small>건축규모</small><b>최고 40층</b></div><div><small>전체 오피스텔</small><b>1,095실</b></div><div><small>공급 안내 타입</small><b>24~53㎡</b></div><div><small>상담 대표번호</small><b>1688-5650</b></div></div>${body}${interest}</article>`};document.addEventListener('click',e=>{const b=e.target.closest('[data-gd-plan]');if(!b)return;const box=b.closest('.gd-plans');box.querySelectorAll('[data-gd-plan]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));box.querySelectorAll('[data-gd-panel]').forEach(x=>x.hidden=x.dataset.gdPanel!==b.dataset.gdPlan)});document.addEventListener('submit',e=>{if(!e.target.matches('.gd-interest-form'))return;e.preventDefault();e.target.querySelector('.gd-form-status').textContent='입력 내용은 전송되지 않았습니다. 온라인 접수 연결 준비 중이니 대표번호 1688-5650으로 문의해 주세요.'});})();
