window.renderDetailPopup=function(p){if(!p.popup)return '';const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const q=p.popup;let hide=false;try{hide=localStorage.getItem('popup-hide-'+p.id)===new Date().toISOString().slice(0,10)}catch(e){}if(hide)return '';return `<div class="detail-popup-layer" data-popup-layer="${E(p.id)}" role="dialog" aria-modal="false" aria-label="${E(p.name)} 분양 안내"><div class="detail-popup-cards">${q.cards.map(c=>`<div class="detail-popup-card"><small>${E(p.name)}</small><h3>${c.title.map(E).join('<br>')}</h3>${(c.items||[]).map(i=>`<div class="popup-item"><b>${E(i[0])}</b>${i[1]?`<span>${E(i[1])}</span>`:''}</div>`).join('')}<a class="popup-call" href="tel:16885650">상담 1688-5650</a><button type="button" class="popup-cta" data-popup-close data-detail-section="interest-${E(p.id)}">관심고객 등록</button></div>`).join('')}</div><div class="detail-popup-actions"><button type="button" data-popup-today="${E(p.id)}">오늘 하루 보지 않기</button><button type="button" data-popup-close>닫기 ✕</button></div></div>`};
document.addEventListener('click',e=>{const t=e.target.closest('[data-popup-today]');if(t){try{localStorage.setItem('popup-hide-'+t.dataset.popupToday,new Date().toISOString().slice(0,10))}catch(_){}t.closest('.detail-popup-layer')?.remove();return}const c=e.target.closest('[data-popup-close]');if(c){c.closest('.detail-popup-layer')?.remove()}});

